<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../classes/NotificationInbox.php';header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store');
if(!isLoggedIn()){http_response_code(401);echo json_encode(['error'=>'Please sign in again.']);exit;}
$uid=(int)$_SESSION['user_id'];$db=(new Database)->getConnection();$inbox=new NotificationInbox($db);$_SESSION['notification_csrf']=$_SESSION['notification_csrf']??bin2hex(random_bytes(32));
try{$inbox->actor($uid);if($_SERVER['REQUEST_METHOD']==='POST'){if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['notification_csrf'],$_POST['csrf'])){http_response_code(403);throw new RuntimeException('Reload your notifications before trying again.');}$action=$_POST['action']??'';if($action==='read'){$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)throw new RuntimeException('Choose a valid notification.');$inbox->mark($uid,(int)$id);}elseif($action==='read_all')$inbox->mark($uid);else throw new RuntimeException('Choose a valid notification action.');}elseif($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);throw new RuntimeException('Request unavailable.');}
    $page=is_scalar($_REQUEST['p']??1)?max(1,(int)($_REQUEST['p']??1)):1;$feed=$inbox->feed($uid,$page,($_REQUEST['unread']??'')==='1');$feed['csrf']=$_SESSION['notification_csrf'];echo json_encode($feed,JSON_INVALID_UTF8_SUBSTITUTE);
}catch(Throwable $e){if(http_response_code()<400)http_response_code(400);echo json_encode(['error'=>$e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'Notifications could not be loaded.']);}
